UPDATE decision_nodes SET data = '{"type":"question","module":4,"title":"Nuchal Cord Check","body":"NUCHAL CORD CHECK\n\nImmediately after the head delivers, **sweep your finger around the baby''s neck** feeling for the umbilical cord.\n\nIf loose, gently slip the cord over the head or shoulder.\nIf too tight to reduce, use the somersault maneuver with the cord intact when feasible.\nDo not routinely clamp and cut a tight cord before the body is delivered. [11]\n\nNuchal cord occurs in 20–30% of deliveries and is usually manageable. [1][2]","citation":[1,2,11],"options":[{"label":"No nuchal cord","description":"Proceed to shoulder delivery","next":"precip-shoulders"},{"label":"Cord present — can slip over head","description":"Reduce cord over head, then deliver","next":"precip-shoulders"},{"label":"Cord too tight to reduce","description":"Try somersault with cord intact; cutting is last resort","next":"precip-nuchal-cut","urgency":"urgent"}],"summary":"Sweep finger around neck immediately after head delivers — nuchal cord in 20-30%, usually manageable"}'::jsonb
