-- Node: precip-nuchal-cut (5 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Tight Nuchal Cord — Preserve Cord Circulation","body":"TIGHT NUCHAL CORD\n\nIf the cord cannot be slipped over the head or shoulder, preserve cord circulation when feasible.\n\nSOMERSAULT MANEUVER [11]\n• Keep the head flexed close to the maternal perineum or thigh.\n• Gently deliver the shoulders while keeping the head close to the perineum.\n• As the body delivers, fold the baby toward the maternal thigh, then unwind the cord.\n• Do not force delivery; suspected shoulder dystocia requires the [Shoulder Dystocia](#/tree/shoulder-dystocia) pathway.\n\n[Somersault technique](#/info/cord-somersault-guide)\n\nCLAMP AND CUT: LAST RESORT\nOnly if the cord prevents delivery and intact-cord delivery is not feasible, double-clamp and cut between clamps.\nDeliver promptly after cutting; placental circulation has been interrupted. Ensure the neonatal resuscitation team is ready. [1][2][11]","citation":[1,2,11],"next":"precip-baby","summary":"Try somersault with cord intact; clamp and cut only if the cord prevents delivery and intact-cord delivery is not feasible","safetyLevel":"warning"}'::jsonb
WHERE id = 'precip-nuchal-cut' AND tree_id = 'precip-delivery';

-- Node: precip-shoulders (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Shoulder Delivery","body":"SHOULDER DELIVERY\n\n**Anterior shoulder (top):**\n• Apply gentle **DOWNWARD traction** on the head (toward the floor)\n• Guide the anterior shoulder under the pubic symphysis\n• The shoulder should slip out — do NOT force\n\n**Posterior shoulder (bottom):**\n• Then apply gentle **UPWARD traction** (toward the ceiling)\n• Deliver the posterior shoulder\n\n**CRITICAL SAFETY POINTS:**\n• Apply traction in the **long axis of the fetal neck** — pulling at an angle risks brachial plexus injury\n• Use steady, gentle traction — never jerk or twist\n• The body will follow the shoulders\n\n**If the head delivers but retracts against the perineum (\"turtle sign\") → [Shoulder Dystocia](#/tree/shoulder-dystocia).** This is an obstetric emergency requiring specific maneuvers (McRoberts, suprapubic pressure). **See [Shoulder Dystocia](#/tree/shoulder-dystocia) consult.** [1][2][3]","citation":[1,2,3],"next":"precip-baby","images":[{"src":"images/precip-delivery/shoulder-delivery.png","alt":"Illustration showing downward and upward traction technique for delivering anterior and posterior fetal shoulders","caption":"Shoulder delivery: gentle downward traction for anterior shoulder, then upward traction for posterior shoulder. Always along the long axis of the neck."}],"summary":"Gentle downward traction for anterior shoulder, then upward — turtle sign = shoulder dystocia emergency","safetyLevel":"warning"}'::jsonb
WHERE id = 'precip-shoulders' AND tree_id = 'precip-delivery';

-- Node: precip-cord (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Cord Clamping & Cutting","body":"CORD CLAMPING AND CUTTING\n\n**DO NOT DROP THE BABY.** The baby is wet and slippery.\n\n1. Place the baby directly on mom''s abdomen — **skin-to-skin contact**\n2. Dry the baby vigorously with a warm towel\n3. Clamp the cord in **two places**, approximately **3 cm apart**, with the first clamp ~3 cm from the baby''s abdomen\n4. **Cut between the two clamps** with sterile scissors\n\nDELAYED CORD CLAMPING\nIf the cord was already cut during tight-cord rescue, proceed with neonatal care; there is no delayed-clamping step.\nFor an intact cord: Current NRP 9th edition (October 2025) guidelines recommend deferred cord clamping for **at least 60 seconds** in vigorous term and preterm newborns who do not require immediate resuscitation. If the baby requires resuscitation, clamp and cut immediately. [5]\n\nNON-STERILE ENVIRONMENT\nIf delivery occurred without sterile instruments, clean the cord stump with antiseptic to prevent omphalitis (cord infection). [1][2]","citation":[1,2,5],"next":"precip-oxytocin","images":[{"src":"images/precip-delivery/cord-clamping.png","alt":"Illustration showing proper umbilical cord clamping technique with two clamps placed 3 cm apart","caption":"Cord clamping: two clamps ~3 cm apart, cut between them. First clamp ~3 cm from the baby''s abdomen."}],"summary":"Do NOT drop the baby — skin-to-skin, deferred cord clamping at least 60 sec unless resuscitation needed"}'::jsonb
WHERE id = 'precip-cord' AND tree_id = 'precip-delivery';

-- Node: precip-baby (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Neonatal Assessment","body":"IMMEDIATE NEONATAL ASSESSMENT\n\nAssess breathing and tone immediately at birth, including during deferred cord clamping.\nDo not delay needed ventilation for cord-clamping timing or APGAR scoring. [12]\n\n**Dry and stimulate** the baby with warm towels. Most babies will cry and become pink within the first minute.\n\nAPGAR SCORING\nAssess at **1 minute and 5 minutes** after delivery:\n• Appearance (color)\n• Pulse (heart rate)\n• Grimace (reflex irritability)\n• Activity (muscle tone)\n• Respiration (breathing effort)\n\nNEONATAL TRANSITION STATISTICS [5]\n• **~90%** of newborns transition without any intervention beyond warmth, drying, and stimulation\n• **~10%** will need additional support (positive pressure ventilation, supplemental O2)\n• **<1%** will need chest compressions\n\n**If the baby is not breathing or heart rate is <100 bpm → initiate NRP ([Neonatal Resuscitation](#/tree/neonatal-resus) Program).** [5]\n\nEnsure the baby stays warm — hypothermia is a significant risk in ED deliveries. [1][5]","citation":[1,5,12],"next":"precip-cord","summary":"Dry/stimulate/warm — 90% need no intervention, 10% need PPV, <1% need compressions, NRP if HR <100"}'::jsonb
WHERE id = 'precip-baby' AND tree_id = 'precip-delivery';

-- Node: precip-placenta (3 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Placental Delivery","body":"STAGE 3 — PLACENTAL DELIVERY\n\nThe placenta typically delivers 5–15 minutes after the baby. [1][2]\n\nSIGNS OF PLACENTAL SEPARATION\n• Cord lengthening — the cord appears to get longer as the placenta detaches\n• Gush of blood — normal separation bleeding\n• Uterine fundus rises — becomes firm and globular\n\nCONTROLLED CORD TRACTION [9][10]\n• A trained clinician should perform controlled cord traction only with a contracted uterus and signs of placental separation.\n• Place one hand just above the pubic symphysis and support the uterus upward while the other hand applies gentle cord traction.\n• Never pull on the cord without uterine counter-traction; do not push downward on the fundus.\n• If the placenta does not descend, stop traction and wait for the next contraction.\n• May ask the patient to push gently.\n\nNEVER force the placenta. Aggressive traction risks uterine inversion.\nEscalate immediately for hemorrhage or instability; if undelivered by 30 minutes, obtain urgent OB assessment for retained placenta. [8][9]\n\nAfter delivery, inspect the placenta for completeness and assess uterine tone and bleeding. [8][10]","citation":[1,2,8,9,10],"next":"precip-placenta-exam","summary":"Gentle cord traction with upward uterine counter-traction above the pubic symphysis; never force or push down on the fundus","safetyLevel":"warning"}'::jsonb
WHERE id = 'precip-placenta' AND tree_id = 'precip-delivery';

-- Node: precip-placenta-exam (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Placental Examination","body":"PLACENTAL EXAMINATION\n\nAfter delivery, inspect the placenta carefully:\n\n**COMPLETENESS**\n• All cotyledons (lobes) present — the maternal surface should look like a complete jigsaw puzzle\n• Check edges for torn vessels (suggests retained succenturiate lobe)\n• **Retained placental fragments → postpartum hemorrhage risk** [8]\n\n**CORD VESSELS**\n• Normal: **2 arteries + 1 vein** (3-vessel cord)\n• Single umbilical artery (2-vessel cord) occurs in ~1% of births — associated with renal and cardiac anomalies\n• Normal cord length: 35–70 cm\n\n**SAVE THE PLACENTA** — OB and pathology will want to examine it. Place in a basin or bag. [1][2]","citation":[1,2],"next":"precip-lacerations","summary":"Check all cotyledons present (jigsaw pattern), count cord vessels (normal = 3), save for pathology","skippable":true}'::jsonb
WHERE id = 'precip-placenta-exam' AND tree_id = 'precip-delivery';

-- Node: precip-oxytocin (6 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":5,"title":"Oxytocin After Birth","body":"OXYTOCIN — POSTPARTUM HEMORRHAGE PREVENTION\n\nGive after birth of all babies, preferably within 1 minute; do not wait for placental delivery. [9]\nMaternal prophylaxis and neonatal assessment occur in parallel; oxytocin need not interrupt deferred cord clamping. [9][12]\n\n[Oxytocin](#/drug/oxytocin/precipitous delivery) 10 units IM once, or 10 units diluted IV over 1–2 minutes if IV access is already available. [9]\nDo NOT give a rapid IV bolus — risk of severe hypotension and tachycardia. [9]\nDo not place an IV solely to give prophylactic oxytocin when IM administration is available. [9]\n\nThis is prophylaxis after birth, not a labor-induction regimen. Confirm that all babies have delivered before administration. [9][10]\n\nPOSTPARTUM ASSESSMENT\nAssess uterine tone and bleeding repeatedly. If the uterus is boggy or hemorrhage develops, call OB immediately and activate the institutional postpartum hemorrhage protocol; begin uterine massage and resuscitation. [8][9]\nRoutine sustained uterine massage is not required for prevention after prophylactic oxytocin; uterine massage is indicated for atony/PPH. [9]","citation":[8,9,10,12],"next":"precip-placenta","treatment":{"firstLine":{"drug":"Oxytocin","dose":"10 units","route":"IM or diluted slow IV","frequency":"once; IV over 1–2 minutes","duration":"after birth of all babies, preferably within 1 minute","notes":"If IV access is already available, use diluted slow IV administration. Do NOT give a rapid IV bolus. Do not wait for placental delivery."},"monitoring":"Uterine tone, vaginal bleeding, blood pressure, heart rate and fluid balance. Escalate immediately for atony or hemorrhage."},"summary":"Oxytocin 10 units IM or diluted slow IV after birth of all babies; do not wait for placenta or give a rapid IV bolus","safetyLevel":"critical"}'::jsonb
WHERE id = 'precip-oxytocin' AND tree_id = 'precip-delivery';

