UPDATE decision_nodes SET data = '{"type":"result","module":5,"title":"Delivery Complete","body":"Delivery complete.\n\n**Congratulate the mother.**\n\nPOSTDELIVERY CHECKLIST\n✓ Uterus firm (not boggy)\n✓ Bleeding controlled\n✓ Vaginal/perineal lacerations assessed and addressed\n✓ Baby assessed — APGAR at 1 and 5 minutes documented\n✓ Placenta examined and saved for pathology\n✓ Prophylactic oxytocin administered\n✓ Skin-to-skin contact maintained\n\nMONITORING\n• Monitor mom for **1 hour post-placenta delivery**: uterine tone, vaginal bleeding, vital signs q15 min\n• Monitor baby: temperature, respiratory status, feeding\n• Document all times: delivery, placenta, APGAR scores, medications\n\nDISPOSITION\n• Admit to OB service for postpartum care\n• Neonatal assessment by pediatrics\n• If delivered at facility without OB: arrange transfer to appropriate facility after stabilization [7]","citation":[1,2,3,5,7,8],"recommendation":"Delivery complete. Monitor mom x1 hour (uterine tone, bleeding, vitals q15 min). Monitor baby (temp, respiratory, feeding). Admit to OB service. APGAR and all times documented.","confidence":"definitive"}'::jsonb
